-- 0015: the tombstone store for natural-key tables (SPEC.md 8.10, story SY-029).
-- Table generated by drizzle-kit, header and triggers written by hand. No table is
-- dropped and no table is rebuilt; only three triggers are replaced.
--
-- WHY
--   `payees.name`, `envelope_categories.category_id` and
--   `budget_allocations(envelope_id, month)` are UNIQUE across deleted rows too
--   (two are inline table constraints, which cannot change without a rebuild). The
--   sync contract says deleted rows never hold a natural key, so a deleted row must
--   be able to step aside for a live row with the same key. It steps into this table.
--
-- COLUMNS
--   tbl       One of the three natural-key tables (CHECK).
--   public_id The row's public id. (tbl, public_id) is the primary key.
--   hlc       The row's HLC, exactly as the `hlc` column of its table (NULL = never
--             sealed or synced; Join clears it).
--   dirty     As `sync_dirty`: holds a version the server has not acknowledged.
--   unsealed  As `sync_unsealed`: written since `hlc` was last stamped.
--   payload   The full row as JSON, in the sync / portable payload shape
--             (SPEC.md 5.3: references are public ids, `deletedAt` is set).
--
-- THE RULE (where a deleted row lives)
--   * A live row always lives in its table.
--   * A deleted row lives in its table, unless another row of that table holds its
--     natural key when it is written, or a live row needs its key later. Then it is
--     moved here (copied, then deleted from the table) and stays here until a newer
--     version of it is live again (an undelete), which moves it back into its table
--     (through natural-key resolution if a live row holds the key by then).
--   * A public id is in exactly one place: its table or this store, never both.
--   Only the engine and portable import move rows (they write here first and then
--   delete the table row). User writes never touch this table: a user creating a
--   payee whose name is held only by a stored tombstone simply inserts a new row,
--   and the services' "revive a deleted row holding the key" still revives a
--   deleted row that is in the table.
--   For every sync purpose a stored row is a row of `tbl`: lookup by public id,
--   last-write-wins, sealing, pushing, acknowledging, Join and portable export.
--
-- TRIGGERS
--   The 0013 `<tbl>_no_hard_delete` guards of the three tables are replaced by ones
--   that let a row leave its table only when this store already holds it, so a
--   deleted row can never be lost by moving it. The other seven guards are unchanged.
CREATE TABLE `sync_tombstones` (
	`tbl` text NOT NULL,
	`public_id` text NOT NULL,
	`hlc` text,
	`dirty` integer DEFAULT false NOT NULL,
	`unsealed` integer DEFAULT false NOT NULL,
	`payload` text NOT NULL,
	`created_at` text DEFAULT (CURRENT_TIMESTAMP),
	PRIMARY KEY(`tbl`, `public_id`),
	CONSTRAINT "sync_tombstones_tbl" CHECK("sync_tombstones"."tbl" IN ('payees', 'envelope_categories', 'budget_allocations'))
);--> statement-breakpoint
DROP TRIGGER IF EXISTS `payees_no_hard_delete`;--> statement-breakpoint
CREATE TRIGGER `payees_no_hard_delete` BEFORE DELETE ON payees
WHEN NOT EXISTS (SELECT 1 FROM sync_tombstones WHERE tbl = 'payees' AND public_id = OLD.public_id)
BEGIN
	SELECT RAISE(ABORT, 'payees must be tombstoned');
END;--> statement-breakpoint
DROP TRIGGER IF EXISTS `envelope_categories_no_hard_delete`;--> statement-breakpoint
CREATE TRIGGER `envelope_categories_no_hard_delete` BEFORE DELETE ON envelope_categories
WHEN NOT EXISTS (SELECT 1 FROM sync_tombstones WHERE tbl = 'envelope_categories' AND public_id = OLD.public_id)
BEGIN
	SELECT RAISE(ABORT, 'envelope_categories must be tombstoned');
END;--> statement-breakpoint
DROP TRIGGER IF EXISTS `budget_allocations_no_hard_delete`;--> statement-breakpoint
CREATE TRIGGER `budget_allocations_no_hard_delete` BEFORE DELETE ON budget_allocations
WHEN NOT EXISTS (SELECT 1 FROM sync_tombstones WHERE tbl = 'budget_allocations' AND public_id = OLD.public_id)
BEGIN
	SELECT RAISE(ABORT, 'budget_allocations must be tombstoned');
END;
